window.listOfSelect=window.listOfSelect||[];function findSelect(inputId){return listOfSelect.find(select=>select.id==="roro-wrapper-"+inputId)}window.roroAddOption=function(inputId,label,value,categoryLabel=null){const select=findSelect(inputId);select&&select.ready.then(()=>select.addOption(label,value,categoryLabel))},window.roroAddOptionsAjax=function(inputId,url,params={}){const select=findSelect(inputId);return select?Promise.all([select.ready,$.getJSON(url,params)]).then(([,options])=>((options||[]).forEach(opt=>select.addOption(opt.label,opt.value,opt.category??null)),options||[])):Promise.resolve([])},window.roroDisableSelect=function(inputId,disable=!0){const select=findSelect(inputId);select&&select.ready.then(()=>select.disable(disable))},window.roroReadonlySelect=function(inputId,readonly=!0){const select=findSelect(inputId);select&&select.ready.then(()=>select.readonly(readonly))},window.roroShowDropDown=function(inputId,show=!0){const select=findSelect(inputId);select&&select.ready.then(()=>select.showDropDown(show))},window.addSelect=function(elt){listOfSelect.push(new RoroSelect(elt.data("id"),elt.data("value")))},window.addMultiSelect=function(elt){listOfSelect.push(new RoroMultiSelect(elt.data("id"),elt.data("name"),elt.data("values")))},$(document).ready(function(){$(".roro-wrapper-select").each(function(){$(this).closest(".roro-repeatable-row").length||addSelect($(this))}),$(".roro-wrapper-multi-select").each(function(){$(this).closest(".roro-repeatable-row").length||addMultiSelect($(this))})});
